use std::io::{BufRead, Write};
use std::path::PathBuf;
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use clap::{Parser, Subcommand};
use futures_util::StreamExt;
use ni_agent::{
    project_history, run_with_history, AgentConfig, AgentEvent, ApprovalMode, ApprovalRequest,
};
use ni_auth::AuthStore;
use ni_core::{now_ms, Event, SessionLog};
use ni_provider::{
    ChatMessage, CompletionRequest, OpenAiConfig, OpenAiProvider, Preset, Provider,
    RecordingProvider, ReplayProvider, StreamEvent, ThinkingMode,
};
use ni_tools::{NetworkMode, SandboxMode, SandboxPolicy};

mod tui;

#[derive(Debug, Parser)]
#[command(name = "ni", version, about = "Minimal, observable coding agent")]
struct Cli {
    #[command(subcommand)]
    command: Option<Command>,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Inspect and create append-only session logs
    Session {
        #[command(subcommand)]
        command: SessionCommand,
    },
    /// Inspect and test model providers
    Provider {
        #[command(subcommand)]
        command: ProviderCommand,
    },
    /// Store API keys in the OS keyring or a 0600 file
    Auth {
        #[command(subcommand)]
        command: AuthCommand,
    },
    /// Run one coding task through the agent loop
    Exec {
        /// Task for the agent
        prompt: String,
        /// Provider preset: deepseek or openai
        #[arg(long, default_value = "deepseek")]
        preset: String,
        /// Override the preset model
        #[arg(long)]
        model: Option<String>,
        /// Maximum model turns
        #[arg(long, default_value_t = 12)]
        max_steps: usize,
        /// Disable DeepSeek thinking mode
        #[arg(long)]
        no_thinking: bool,
        /// Working directory (defaults to cwd)
        #[arg(long)]
        cwd: Option<PathBuf>,
        /// Directory for the session JSONL (defaults to ~/.ni/sessions)
        #[arg(long)]
        session_dir: Option<PathBuf>,
        /// Resume an existing session JSONL
        #[arg(long)]
        resume: Option<PathBuf>,
        /// Record normalized provider turns to a fixture JSON
        #[arg(long)]
        record: Option<PathBuf>,
        /// Replay normalized provider turns from a fixture JSON
        #[arg(long)]
        replay: Option<PathBuf>,
        /// Sandbox: read-only, workspace-write, or full-access
        #[arg(long, default_value = "workspace-write")]
        sandbox: String,
        /// Approval: ask, on-failure, or never
        #[arg(long, default_value = "on-failure")]
        approval: String,
        /// Network: on or off
        #[arg(long, default_value = "off")]
        network: String,
    },
    /// Start the interactive linear TUI
    Tui {
        /// Provider preset: deepseek or openai
        #[arg(long, default_value = "deepseek")]
        preset: String,
        /// Override the preset model
        #[arg(long)]
        model: Option<String>,
        /// Disable DeepSeek thinking mode
        #[arg(long)]
        no_thinking: bool,
        /// Working directory (defaults to cwd)
        #[arg(long)]
        cwd: Option<PathBuf>,
        /// Directory for the session JSONL (defaults to ~/.ni/sessions)
        #[arg(long)]
        session_dir: Option<PathBuf>,
        /// Resume an existing session JSONL
        #[arg(long)]
        resume: Option<PathBuf>,
        /// Sandbox: read-only, workspace-write, or full-access
        #[arg(long, default_value = "workspace-write")]
        sandbox: String,
        /// Approval: ask, on-failure, or never
        #[arg(long, default_value = "on-failure")]
        approval: String,
        /// Network: on or off
        #[arg(long, default_value = "off")]
        network: String,
        /// Replay normalized provider turns from a fixture JSON
        #[arg(long)]
        replay: Option<PathBuf>,
    },
}

#[derive(Debug, Subcommand)]
enum SessionCommand {
    /// Create a session and print its path
    New {
        /// Directory for the session file
        #[arg(long)]
        dir: Option<PathBuf>,
    },
    /// Print the events in a session file
    Show {
        /// Path to a .jsonl session file
        path: PathBuf,
    },
    /// List session files
    List {
        /// Directory containing session files
        #[arg(long)]
        dir: Option<PathBuf>,
    },
}

#[derive(Debug, Subcommand)]
enum AuthCommand {
    /// Store an API key (hidden prompt, or --stdin for scripts)
    Set {
        /// Provider: deepseek or openai
        provider: String,
        /// Read one line from stdin instead of prompting
        #[arg(long)]
        stdin: bool,
    },
    /// Show where each provider's credential comes from
    Status,
    /// Remove stored credentials for a provider
    Unset {
        /// Provider: deepseek or openai
        provider: String,
    },
}

#[derive(Debug, Subcommand)]
enum ProviderCommand {
    /// List built-in presets and whether their API key is present
    List,
    /// Stream one prompt through a provider
    Test {
        /// Preset: deepseek or openai
        #[arg(long, default_value = "deepseek")]
        preset: String,
        /// Override the preset model
        #[arg(long)]
        model: Option<String>,
        /// Prompt for the test request
        #[arg(long)]
        prompt: Option<String>,
        /// Disable DeepSeek thinking mode
        #[arg(long)]
        no_thinking: bool,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Some(Command::Session { command }) => run_session(command),
        Some(Command::Provider { command }) => run_provider(command).await,
        Some(Command::Auth { command }) => run_auth(command),
        Some(Command::Exec {
            prompt,
            preset,
            model,
            max_steps,
            no_thinking,
            cwd,
            session_dir,
            resume,
            record,
            replay,
            sandbox,

//! Linear in-process TUI.
//!
//! It only consumes `AgentEvent`s and calls the same `run_with_history` entry
//! point as headless exec. No loop internals are imported here.

use std::io::Write;
use std::time::{Duration, Instant};

use anyhow::Result;
use crossterm::event::{self, Event as TerminalEvent, KeyCode, KeyEvent, KeyModifiers};
use crossterm::terminal;
use ni_agent::{project_history, run_with_history, AgentConfig, AgentEvent, ApprovalRequest};
use ni_core::{load, now_ms, Event, SessionLog};
use ni_provider::{ChatMessage, Provider};

pub async fn run(
    provider: &dyn Provider,
    session: &mut SessionLog,
    config: &AgentConfig,
    history: Vec<ChatMessage>,
) -> Result<()> {
    let mut history = history;
    let mut allow_session = false;

    tokio::spawn(async {
        let mut last: Option<Instant> = None;
        loop {
            if tokio::signal::ctrl_c().await.is_err() {
                break;
            }
            let now = Instant::now();
            if last
                .map(|instant| now.duration_since(instant) < Duration::from_secs(2))
                .unwrap_or(false)
            {
                eprintln!("\nforce exit");
                std::process::exit(130);
            }
            last = Some(now);
        }
    });

    loop {
        print!("\nni> ");
        std::io::stdout().flush()?;
        let mut input = String::new();
        if std::io::stdin().read_line(&mut input)? == 0 {
            break;
        }
        let prompt = input.trim();
        if prompt.is_empty() {
            continue;
        }
        if matches!(prompt, "exit" | "quit" | ":q") {
            break;
        }

        let mut line_open = false;
        let mut thinking = false;

        let mut approver = |request: &ApprovalRequest| -> bool {
            if allow_session {
                eprintln!("\nauto-approved for this session: {}", request.summary);
                return true;
            }
            match prompt_approval(request) {
                ApprovalChoice::Allow => true,
                ApprovalChoice::Deny => false,
                ApprovalChoice::Session => {
                    allow_session = true;
                    true
                }
            }
        };

        let mut observer = |event: AgentEvent| match event {
            AgentEvent::TextDelta(delta) => {
                print!("{delta}");
                let _ = std::io::stdout().flush();
                line_open = !delta.ends_with('\n');
            }
            AgentEvent::ReasoningDelta(_) => {
                if !thinking {
                    if line_open {
                        println!();
                        line_open = false;
                    }
                    eprintln!("thinking…");
                    thinking = true;
                }
            }
            AgentEvent::ToolCall { name, input } => {
                if line_open {
                    println!();
                    line_open = false;
                }
                eprintln!("→ {name} {}", compact_json(&input));
            }
            AgentEvent::ToolResult { name, ok, summary } => {
                eprintln!("← {name} {} {}", if ok { "ok" } else { "error" }, summary);
            }
            AgentEvent::TurnEnd { usage } => {
                if line_open {
                    println!();
                    line_open = false;
                }
                eprintln!(
                    "turn usage: in={} out={} cached={}",
                    usage.input_tokens, usage.output_tokens, usage.cached_tokens
                );
            }
        };

        let result = {
            let run = run_with_history(
                provider,
                session,
                config,
                prompt,
                history.clone(),
                &mut approver,
                &mut observer,
            );
            tokio::pin!(run);
            tokio::select! {
                result = &mut run => Some(result),
                _ = tokio::signal::ctrl_c() => None,
            }
        };

        if line_open {
            println!();
        }

        match result {
            None => {
                let _ = session.append(&Event::SessionEnd { ts: now_ms() });
                history = project_history(&load(session.path())?.events)?;
                eprintln!("cancelled; Ctrl-C again within 2s to exit");
            }
            Some(Ok(outcome)) => {
                eprintln!(
                    "done: {} turns, input={} output={} cached={}",
                    outcome.turns,
                    outcome.usage.input_tokens,
                    outcome.usage.output_tokens,
                    outcome.usage.cached_tokens
                );
                history = project_history(&load(session.path())?.events)?;
            }
            Some(Err(error)) => {
                eprintln!("error: {error:#}");
                history = project_history(&load(session.path())?.events)?;
            }
        }
    }

    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ApprovalChoice {
    Allow,
    Deny,
    Session,
}

fn prompt_approval(request: &ApprovalRequest) -> ApprovalChoice {
    println!();
    eprintln!("approval required: {}", request.summary);
    if let Some(preview) = &request.preview {
        eprintln!("{preview}");
    }

    if terminal::enable_raw_mode().is_ok() {
        eprint!("[a]llow  [d]eny  [s]ession  ");
        let _ = std::io::stderr().flush();
        let choice = loop {
            match event::read() {
                Ok(TerminalEvent::Key(KeyEvent {
                    code, modifiers, ..
                })) => match code {
                    KeyCode::Char('a') | KeyCode::Char('A') => {
                        break ApprovalChoice::Allow;
                    }
                    KeyCode::Char('d') | KeyCode::Char('D') | KeyCode::Esc => {
                        break ApprovalChoice::Deny;
                    }
                    KeyCode::Char('s') | KeyCode::Char('S') => {
                        break ApprovalChoice::Session;
                    }
                    KeyCode::Char('c') if modifiers.contains(KeyModifiers::CONTROL) => {
                        break ApprovalChoice::Deny;
                    }
                    _ => {}
                },
                Ok(_) => {}
                Err(_) => break ApprovalChoice::Deny,
            }
        };

//! Minimal turn loop.
//!
//! The loop owns the conversation order, tool dispatch, and session events. It
//! does not know about wire formats or concrete tools; those live in
//! `ni-provider` and `ni-tools`.

use std::collections::BTreeMap;
use std::path::PathBuf;

use anyhow::{bail, Result};
use futures_util::StreamExt;
use ni_core::{now_ms, Event, SessionLog, ToolCall, Usage};
use ni_provider::{ChatMessage, CompletionRequest, Provider, StreamEvent};
use ni_tools::{SandboxPolicy, Toolbox};
