}

impl WireToolCall {
    pub fn from_tool_call(call: &ToolCall) -> Self {
        let arguments = if call.input.is_null() {
            "{}".to_string()
        } else {
            serde_json::to_string(&call.input).unwrap_or_else(|_| "{}".to_string())
